// 生成请求ID和初始化
msg.requestId = 'req_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
msg.startTime = Date.now();
msg.version = '1.0';

// 解析查询参数
if (msg.req.query) {
    msg.params = msg.req.query;
}

// 解析POST数据
if (msg.payload && typeof msg.payload === 'object') {
    msg.data = msg.payload;
}

// 记录请求开始
console.log(`[${msg.requestId}] 请求开始: ${msg.req.method} ${msg.req.url}`);

return msg;

function validateRequest(msg) {
    const errors = [];

    // 根据不同的API端点定义验证规则
    const validationRules = {
        '/api/wx/stats/overview': {
            method: 'GET',
            params: {
                optional: ['useCache', 'siteId']
            }
        },
        '/api/site/sites': {
            method: 'GET',
            params: {
                optional: ['page', 'pageSize', 'status']
            }
        },
        '/api/device/status': {
            method: 'GET',
            params: {
                required: ['siteId'],
                optional: ['deviceType', 'status']
            }
        }
    };

    const rule = validationRules[msg.req.url.split('?')[0]];

    if (rule) {
        // 验证HTTP方法
        if (msg.req.method !== rule.method) {
            errors.push({
                field: 'method',
                message: `不支持的HTTP方法: ${msg.req.method}`
            });
        }

        // 验证必填参数
        if (rule.params && rule.params.required) {
            rule.params.required.forEach(field => {
                if (!msg.params || msg.params[field] === undefined || msg.params[field] === '') {
                    errors.push({
                        field: field,
                        message: `${field}参数不能为空`
                    });
                }
            });
        }
    }

    if (errors.length > 0) {
        msg.statusCode = 400;
        msg.error = {
            type: 'VALIDATION_ERROR',
            details: errors
        };
        return [null, msg]; // 输出到错误处理分支
    }

    return [msg, null]; // 输出到正常处理分支
}

const [success, error] = validateRequest(msg);
if (error) {
    return [null, error];
}
return [success, null];

function checkCache(msg) {
    // 只对GET请求启用缓存
    if (msg.req.method !== 'GET') {
        return msg;
    }

    // 生成缓存键
    const cacheKey = `${msg.req.url}_${JSON.stringify(msg.params || {})}`;

    // 检查是否强制刷新
    const forceRefresh = msg.params && msg.params.forceRefresh === 'true';

    if (!forceRefresh) {
        // 从context获取缓存数据
        const cachedData = context.get(cacheKey);

        if (cachedData) {
            const cacheAge = Date.now() - cachedData.timestamp;
            const maxAge = 5 * 60 * 1000; // 5分钟缓存

            if (cacheAge < maxAge) {
                console.log(`[${msg.requestId}] 使用缓存数据`);

                msg.payload = {
                    code: 200,
                    message: 'success',
                    data: cachedData.data,
                    timestamp: Date.now(),
                    requestId: msg.requestId,
                    version: msg.version,
                    fromCache: true
                };

                return [null, msg]; // 直接返回缓存结果
            }
        }
    }

    // 保存缓存键供后续使用
    msg.cacheKey = cacheKey;
    return [msg, null]; // 继续处理
}

const [continue, cached] = checkCache(msg);
if (cached) {
    return [null, cached];
}
return [continue, null];

