function processSitesData(msg) {
    try {
        const page = parseInt(msg.params.page) || 1;
        const pageSize = parseInt(msg.params.pageSize) || 20;

        // 模拟站点数据
        const allSites = [
            {
                id: 'site001',
                name: '污水处理厂A',
                location: '北京市朝阳区',
                status: 'online',
                deviceCount: 25,
                lastUpdateTime: Date.now(),
                coordinates: {
                    lat: 39.9042,
                    lng: 116.4074
                }
            },
            {
                id: 'site002',
                name: '污水处理厂B',
                location: '上海市浦东新区',
                status: 'online',
                deviceCount: 18,
                lastUpdateTime: Date.now(),
                coordinates: {
                    lat: 31.2304,
                    lng: 121.4737
                }
            }
        ];

        const startIndex = (page - 1) * pageSize;
        const endIndex = startIndex + pageSize;
        const sites = allSites.slice(startIndex, endIndex);

        const data = {
            sites: sites,
            pagination: {
                page: page,
                pageSize: pageSize,
                total: allSites.length,
                hasMore: endIndex < allSites.length
            }
        };

        msg.businessData = data;
        return msg;

    } catch (error) {
        msg.statusCode = 500;
        msg.error = {
            type: 'BUSINESS_ERROR',
            message: error.message
        };
        return msg;
    }
}

return processSitesData(msg);

