function formatResponse(msg) {
    const processingTime = Date.now() - msg.startTime;

    if (msg.error) {
        // 错误响应
        msg.payload = {
            code: msg.statusCode || 500,
            message: msg.error.message || '服务器内部错误',
            data: null,
            error: {
                type: msg.error.type || 'UNKNOWN_ERROR',
                details: msg.error.details || []
            },
            timestamp: Date.now(),
            requestId: msg.requestId,
            version: msg.version,
            processingTime: processingTime
        };

        console.error(`[${msg.requestId}] 请求失败: ${msg.error.message} (${processingTime}ms)`);
    } else {
        // 成功响应
        msg.payload = {
            code: 200,
            message: 'success',
            data: msg.businessData,
            timestamp: Date.now(),
            requestId: msg.requestId,
            version: msg.version,
            processingTime: processingTime
        };

        // 缓存成功的结果
        if (msg.cacheKey && msg.businessData) {
            context.set(msg.cacheKey, {
                data: msg.businessData,
                timestamp: Date.now()
            });
        }

        console.log(`[${msg.requestId}] 请求成功 (${processingTime}ms)`);
    }

    return msg;
}

return formatResponse(msg);

// 设置响应头
msg.headers = {
    'Content-Type': 'application/json',
    'X-Request-ID': msg.requestId,
    'X-Processing-Time': (Date.now() - msg.startTime) + 'ms',
    'Cache-Control': msg.payload.fromCache ? 'public, max-age=300' : 'no-cache',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization'
};

// 设置状态码
msg.statusCode = msg.payload.code;

return msg;
